reference_query:
SELECT DISTINCT ?item ?itemLabel ?sense ?lexeme ?lemma ?genre ?genreLabel WHERE {
?lexeme rdf:type ontolex:LexicalEntry;
dct:language wd:Q150;
wikibase:lemma ?lemma;
ontolex:sense ?sense;
wdt:P5185 ?genre.
?sense wdt:P5137 ?item.
?item (wdt:P31/(wdt:P279*)) wd:Q12737077;
rdfs:label ?itemLabel.
FILTER((LANG(?itemLabel)) = "fr")
?genre rdfs:label ?genreLabel.
FILTER((LANG(?genreLabel)) = "fr")
}
ORDER BY (?item) (?lemma) (?genre)

SELECT ?q (min(?image) AS ?img) (GROUP_CONCAT(DISTINCT(?qLabel); separator=", ") AS ?label) (COUNT(DISTINCT ?sitelink) as ?linkcount) {
?q (wdt:P31/wdt:P279*) wd:Q3305213 .
?sitelink schema:about ?q .
OPTIONAL { ?q wdt:P18 ?image }
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en" .
?q rdfs:label ?qLabel .
}
}
GROUP BY ?q
ORDER BY DESC(?linkcount)
LIMIT 500

SELECT DISTINCT ?Donejakue_bidea ?Donejakue_bideaLabel ?koordenatuak ?layerLabel WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "eu,es,en". }
?Donejakue_bidea (wdt:P361*) wd:Q41150.
?Donejakue_bidea wdt:P131*/^wdt:P527 wd:Q47588.
?Donejakue_bidea wdt:P625 ?koordenatuak.
?Donejakue_bidea wdt:P361 ?bidea.
?bidea wdt:P31 wd:Q337912.
BIND (?bidea AS ?layer)
}

SELECT ?q ?qLabel (COUNT(?person) AS ?count) WHERE {
?q wdt:P31/wdt:P279* wd:Q52085914.
?person wdt:P69 ?q.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?q ?qLabel
ORDER BY DESC(?count)

SELECT DISTINCT ?q ?qLabel WHERE {
?q wdt:P31 wd:Q3624078 ; wdt:P37 ?l1 ; wdt:P37 ?l2 .
FILTER ( STR(?l1) < STR(?l2) ) .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?qLabel

SELECT ?country ?countryLabel (COUNT(DISTINCT ?item) AS ?count) WHERE {
?item (wdt:P31|wdt:P279) wd:Q51404;
wdt:P17 ?country;
wdt:P571 ?time.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY (?countryLabel)

SELECT ?ingredienteLabel (COUNT (?ingrediente) AS ?count)
WHERE
{
?sandwich wdt:P31?/wdt:P279* wd:Q28803;
wdt:P527 ?ingrediente.
SERVICE wikibase:label { bd:serviceParam wikibase:language "es", "en". }
}
GROUP BY ?ingredienteLabel
ORDER BY DESC (?count)

SELECT ?creator ?creatorLabel ?placebirthLabel ?geoloc where {
?item wdt:P31/wdt:P279* wd:Q838948 . # oeuvre d'art et ss-classe
?item wdt:P608 wd:Q20980830 . # du projet Europeana 280
?item wdt:P170 ?creator . # createur
?creator wdt:P19 ?placebirth . # lieu de naissance
?placebirth wdt:P625 ?geoloc . #coordonnees geo
SERVICE wikibase:label {
bd:serviceParam wikibase:language "fr,es,en" .
}
}

SELECT ?subj ?label WHERE
{ ?subj wdt:P4102 ?atlasID ;
rdfs:label ?label filter (lang(?label) = "g1")
}

SELECT (?link as ?q) (?nameplusdesc AS ?qLabel) (SAMPLE(?image) AS ?img) WHERE {
?work wdt:P195/wdt:P361 wd:Q63160499; wdt:P18 ?image ; wdt:P973 ?link; wdt:P180 ?depicted.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".
?depicted rdfs:label ?name . ?depicted schema:description ?desc }
BIND(IF(BOUND(?desc), CONCAT(?name, ", ", ?desc), ?name) AS ?nameplusdesc)
} GROUP BY ?link ?nameplusdesc
ORDER BY UCASE(?qLabel)

select ?site ?siteLabel ?siteDescription ?location ?photo ?placeNameLabel ?heritageLabel (?heritage as ?layer)
WHERE {
?site wdt:P31 ?place. ?place wdt:P279* wd:Q744099 .
?site wdt:P625 ?location.
optional {
?site wdt:P31 ?placeName.
?site wdt:P18 ?photo.
}
?site wdt:P1435 ?heritage.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,lt,es,[AUTO_LANGUAGE]". }
}
#defaultView:Map

SELECT ?software ?softwareLabel ?field ?fieldLabel {
{ ?software wdt:P31/wdt:P279* wd:Q5500964. }
UNION
{ ?software wdt:P275/wdt:P279* wd:Q1156659. }
?software wdt:P101|wdt:P136|wdt:P366 ?field.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

select ?item ?itemLabel ?img where {
?item wdt:P31 wd:Q1195942 .
?item wdt:P31/wdt:P279* wd:Q24398318 .
optional {?item wdt:P18 ?img .}
}

SELECT ?companyLabel (GROUP_CONCAT(DISTINCT ?founderLabel; separator=", ") AS ?founders) WHERE {
?company wdt:P112 ?founder;
wdt:P17 wd:Q30.
FILTER EXISTS { ?company wdt:P414|wdt:P249 []. }
?founder (wdt:P22|wdt:P25)?/wdt:P19 ?placeOfBirth.
MINUS { ?placeOfBirth wdt:P17 wd:Q30. }
OPTIONAL { ?founder rdfs:label ?founderLabel. FILTER(LANG(?founderLabel) = "en"). }
OPTIONAL { ?company wdt:P2403|wdt:P2137|wdt:P2139|wdt:P2226|wdt:P2295 ?money. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?companyLabel
ORDER BY DESC(MAX(?money)) ?companyLabel

SELECT ?item ?articlename ?itemLabel ?itemDescription ?sl
WHERE {
VALUES ?dod {"+2001-08-25"^^xsd:dateTime}
?dod ^wdt:P570 ?item .
?item wikibase:sitelinks ?sl .
?item ^schema:about ?article .
?article schema:isPartOf <https://en.wikipedia.org/>;
schema:name ?articlename .
SERVICE wikibase:label
{
bd:serviceParam wikibase:language "en" .
?item rdfs:label ?itemLabel .
?item schema:description ?itemDescription .
}
BIND(REPLACE(?itemLabel, "^.*(?<! [Vv][ao]n| [Dd][aeiu]| [Dd][e][lns]| [Ll][ae]) (?!([SJ]r\\.?|[XVI]+)$)", "") AS ?sortname)
} ORDER BY ASC(UCASE(?sortname)) ASC(UCASE(?itemLabel))

SELECT ?song ?female_name ?title (LANG(?title) AS ?title_language) ?note
WITH
{
SELECT DISTINCT ?song ?title
{
?song wdt:P31 / wdt:P279 * wd:Q105543609 .
?song wdt:P1476 ?title .
}
} AS %songs
{
{
INCLUDE %songs
?female_name wdt:P1705 ?title .
?female_name wdt:P31 wd:Q11879590 .
}
UNION
{
INCLUDE %songs
FILTER (LANG(?title) != "mul")
BIND (STRLANG(STR(?title), "mul") AS ?title_mul)
?female_name wdt:P1705 ?title_mul .
?female_name wdt:P31 wd:Q11879590 . hint:Prior hint:runLast true.
BIND ("match one to multiple" AS ?note)
}
}

SELECT ?Masonic_Lodge ?Masonic_LodgeLabel (sample(?Masonic_LodgeTitle) as ?wpTitle) WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?Masonic_Lodge wdt:P31 wd:Q1454597.
OPTIONAL {
?article schema:about ?Masonic_Lodge ;
schema:name ?Masonic_LodgeTitle
}
} group by ?Masonic_Lodge ?Masonic_LodgeLabel

SELECT ?station ?stationLabel ?cds ?line ?trackLabel ?track ?image {
{SELECT * {
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.BFS" ; gas:in wd:Q1990205 ; gas:out ?station ; gas:out1 ?depth ; gas:out2 ?pred .
gas:program gas:linkType wdt:P197 . }
FILTER(?station != wd:Q1990205)
?station wdt:P625 ?cds ;
wdt:P17 wd:Q55 .
?station p:P197 ?adjST .
?adjST ps:P197 ?adj ;
pq:P81 ?track .
?pred p:P625/psv:P625/wikibase:geoLatitude ?lat1 ; p:P625/psv:P625/wikibase:geoLongitude ?lon1 .
?station p:P625/psv:P625/wikibase:geoLatitude ?lat2 ; p:P625/psv:P625/wikibase:geoLongitude ?lon2 .
BIND(CONCAT('LINESTRING(', STR(?lon1), ' ', STR(?lat1), ',', STR(?lon2), ' ', STR(?lat2), ')') AS ?str) . BIND(STRDT(?str, geo:wktLiteral) AS ?line)}
}
OPTIONAL { ?station wdt:P18 ?image .}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel (COUNT(distinct ?sitelink) as ?count) (SAMPLE(?picture) as ?picture)
WHERE
{
?item wdt:P31 wd:Q5 .
?item wdt:P21 wd:Q6581072 .
?item wdt:P106 ?dancer .
VALUES ?dancer {
wd:Q5716684
wd:Q805221
wd:Q2490358
}
?item wdt:P18 ?picture .
?sitelink schema:about ?item .
FILTER EXISTS { ?wen schema:about ?item . ?wen schema:inLanguage "en" }
FILTER NOT EXISTS { ?wfr schema:about ?item . ?wfr schema:inLanguage "fr" }
SERVICE wikibase:label {
bd:serviceParam wikibase:language "fr,en" .
}
}
GROUP BY ?item ?itemLabel
ORDER BY DESC(?count)

SELECT ?i ?iLabel ?coords ?url WHERE {
?i wdt:P31/wdt:P279* wd:Q57821 .
?i wdt:P973 ?url .
?i wdt:P625 ?coords .
FILTER (REGEX(STR(?url),"atlasofmutualheritage"))
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?sandwich ?ingredient ?sandwichLabel ?ingredientLabel
WHERE
{
?sandwich wdt:P31?/wdt:P279* wd:Q28803;
wdt:P527 ?ingredient.
MINUS { ?ingredient wdt:P279* wd:Q7802. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en", "fr". }
}
ORDER BY UCASE(STR(?sandwichLabel))

SELECT ?book ?title ?illustratorLabel ?publisherLabel ?published
WHERE
{
?book wdt:P50 wd:Q35610. # required wdt:P50
OPTIONAL { # match all or none from group:
?book wdt:P1476 ?title; # required wdt:P1476
wdt:P110 ?illustrator; # required wdt:P110
wdt:P123 ?publisher; # required wdt:P123
wdt:P577 ?published. # required wdt:P577
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?item ?itemLabel ?itemDescription (MIN(?date2) AS ?date) WHERE {
?item wdt:P57 wd:Q53001;
wdt:P577 ?date2.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en, fr". }
}
GROUP BY ?item ?itemLabel ?itemDescription
ORDER BY (?date)

select distinct ?itemLabel ?size ?percentage_online ?rgb where {
?item wdt:P17 wd:Q213 .
?item p:P1436 ?statement.
?statement ps:P1436 ?size ;
pq:P585 ?date filter(year(?date)= 2021 )
minus {?statement pq:P518 [] .}
optional {?item p:P1436 [ps:P1436 ?size_online ; pq:P518 wd:Q106474029 ; pq:P585 ?date ] .}
bind ((100 * ?size_online / ?size) as ?percentage_online)
BIND(if
(?percentage_online < 10, "FF0000",
if (?percentage_online < 20, "E21C00",
if (?percentage_online < 30,"C63800",
if (?percentage_online < 40, "AA5500",
if (?percentage_online < 50, "8D7100",
if (?percentage_online < 60, "718D00",
if (?percentage_online < 70, "55AA00",
if (?percentage_online < 80, "38C600",
if (?percentage_online < 90, "1CE200", "00FF00"))))))))) as ?rgb) .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,cs". }
}

SELECT
?item ?itemLabel ?pic
WHERE
{
wd:Q109639255 wdt:P6803 ?item .
OPTIONAL {?item wdt:P18 ?pic}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?item ?itemLabel ?countryLabel ?area ?population
WHERE
{
?item wdt:P31/wdt:P279* wd:Q10864048 ; # first-level subdivision
wdt:P17 ?country ; # country
p:P2046/psv:P2046 [ # area
wikibase:quantityAmount ?baseArea;
wikibase:quantityUnit [
p:P2370/psv:P2370 [
wikibase:quantityAmount ?unitArea;
wikibase:quantityUnit wd:Q25343
]
]
] ;
wdt:P1082 ?population . # population
BIND(ROUND(?baseArea * ?unitArea / 1000000) AS ?area) .
FILTER NOT EXISTS { ?item wdt:P194 [] } # without legislature
FILTER NOT EXISTS { ?item wdt:P576 [] } # filter dissolved subdivisions
FILTER NOT EXISTS { ?country wdt:P576 [] } # filter dissolved countries
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?population)
LIMIT 500

SELECT ?pride ?time ?image {
?pride (wdt:P31|wdt:P279) wd:Q51404;
wdt:P571 ?time.
OPTIONAL {?pride wdt:P18 ?image}
}

SELECT ?item ?itemLabel (SAMPLE(?holder) as ?sample) (COUNT(DISTINCT ?holder) as ?ct)
{
?item wdt:P31 wd:Q1240901 .
OPTIONAL { ?holder wdt:P2358 ?item }
MINUS { ?item wdt:P31 wd:Q4167410 }
MINUS { ?item wdt:P31 wd:Q101352 }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" .}
}
GROUP BY ?item ?itemLabel

SELECT ?item ?itemLabel ?official_website WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?item wdt:P1343 wd:Q76510930.
OPTIONAL { ?item wdt:P856 ?official_website. }
}
ORDER BY ASC(?itemLabel)

SELECT ?disciplineLabel ?genderLabel (AVG(?height_in_m) AS ?averageheight) (COUNT(?person) AS ?number)
WHERE {
?person wdt:P2416 ?discipline ;
wdt:P641 wd:Q38108 .
?person wdt:P21 ?gender .
?person p:P2048/psn:P2048/wikibase:quantityAmount ?height_in_m .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?disciplineLabel ?genderLabel
ORDER BY ?averageheight

SELECT DISTINCT ?coactorLabel (COUNT(?film) as ?films) WHERE {
?film wdt:P31 wd:Q11424 ; wdt:P161 wd:Q9535 ; wdt:P161 ?coactor.
FILTER(?coactor != wd:Q9535)
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?coactorLabel

SELECT ?item1 ?image ?item1Label ?item2 ?image2 ?item2Label ?edgeLabel
WITH { SELECT ?item1 WHERE {
VALUES ?item1 {wd:Q233009 wd:Q55264 wd:Q18527930 wd:Q61412 wd:Q9061 wd:Q1170115 wd:Q1453055 wd:Q5541515 wd:Q5729524 wd:Q1138080 wd:Q82133 wd:Q20081025 wd:Q860807}
} } AS %item1
WITH {SELECT (?item1 AS ?item2) WHERE {INCLUDE %item1} } AS %item2
WHERE {
INCLUDE %item1.
INCLUDE %item2.
?item1 ?prop ?item2.
?edge wikibase:directClaim ?prop ; a wikibase:Property
OPTIONAL {?item1 wdt:P18 ?image}
OPTIONAL {?item2 wdt:P18 ?image2}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?item ?itemLabel ?num ?itemDescription WHERE {
VALUES ?occ {wd:Q639669}
?item wdt:P31 wd:Q5 ;
wdt:P21 wd:Q6581072 ;
(wdt:P106/(wdt:P279*)) ?occ;
wdt:P106 ?occupation .
?item wikibase:sitelinks ?num.
?item wdt:P27 ?nacionalidad .
?nacionalidad wdt:P17 ?country .
?country (wdt:P361/(wdt:P361*)) wd:Q12585 .
FILTER(?num >= 1)
MINUS {
?art schema:about ?item.
?art schema:isPartOf <https://es.wikipedia.org/>.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "es,en". }
}
ORDER BY DESC(?num)

SELECT ?s ?desc
WHERE
{
?s wdt:P279 wd:Q7725634 .
OPTIONAL {
?s rdfs:label ?desc FILTER (lang(?desc) = "en").
}
}

SELECT ?station ?stationLabel ?cds ?line ?trackLabel ?track ?image {
{SELECT * {
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.BFS" ; gas:in wd:Q1990205 ; gas:out ?station ; gas:out1 ?depth ; gas:out2 ?pred .
gas:program gas:linkType wdt:P197 . }
FILTER(?station != wd:Q1990205)
?station wdt:P625 ?cds ;
wdt:P17 wd:Q145 .
?station p:P197 ?adjST .
?adjST ps:P197 ?adj ;
pq:P81 ?track .
?pred p:P625/psv:P625/wikibase:geoLatitude ?lat1 ; p:P625/psv:P625/wikibase:geoLongitude ?lon1 .
?station p:P625/psv:P625/wikibase:geoLatitude ?lat2 ; p:P625/psv:P625/wikibase:geoLongitude ?lon2 .
BIND(CONCAT('LINESTRING(', STR(?lon1), ' ', STR(?lat1), ',', STR(?lon2), ' ', STR(?lat2), ')') AS ?str) . BIND(STRDT(?str, geo:wktLiteral) AS ?line)}
}
OPTIONAL { ?station wdt:P18 ?image .}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?article ?person ?personLabel ?picGrave ?coord ?bd ?graveplot2 ?layer WHERE {
{
?person wdt:P119 wd:Q311 ;
p:P119 [
pq:P965 ?graveplot];
wdt:P569 ?bd .
?person wdt:P19 ?city .
?city wdt:P625 ?coord .
OPTIONAL{ ?person wdt:P1442 ?picGrave .}
OPTIONAL {
?article schema:about ?person .
?article schema:inLanguage "fr" .
?article schema:isPartOf <https://fr.wikipedia.org/> .}
BIND (CONCAT("Division ",?graveplot) AS ?graveplot2)
BIND(
IF(?bd < "1700-01-01T00:00:00Z"^^xsd:dateTime, "<1700",
IF(?bd < "1800-01-01T00:00:00Z"^^xsd:dateTime, "18e siecle",
IF(?bd < "1900-01-01T00:00:00Z"^^xsd:dateTime, "19e siecle",
IF(?bd < "2000-01-01T00:00:00Z"^^xsd:dateTime, "20e siecle",
"21e siecle"))))
AS ?layer).
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr"}
}
Order by ?personLabel

SELECT DISTINCT ?lighthouse ?lighthouseName ?countryLabel (concat(str(?latitude), ", ", str(?longitude)) AS ?coordinates) ?height ?builtDateLabel ?functionalLabel ?wikipediaUrl
WHERE
{
?lighthouse wdt:P31 wd:Q39715. # find all instances of lighthouse
?country wdt:P30 wd:Q18. # find all instances of country in South America
?lighthouse wdt:P17 ?country. # find lighthouses in South American countries
OPTIONAL {
?lighthouse wdt:P17 ?country.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
OPTIONAL {
?lighthouse wdt:P625 ?coordinates.
BIND(xsd:float(STRAFTER(STR(?coordinates), "Point(")) AS ?longitude)
BIND(xsd:float(STRAFTER(STR(?coordinates), " " )) AS ?latitude)
}
OPTIONAL { ?lighthouse wdt:P2048 ?height. }
OPTIONAL { ?lighthouse wdt:P571 ?builtDate. }
OPTIONAL {
?lighthouse p:P1433/ps:P1433 ?wikipediaUrl. # get the English Wikipedia page URL
FILTER (LANG(?wikipediaUrl) = '' || LANG(?wikipediaUrl) = 'en')
}
OPTIONAL {
?lighthouse p:P1317 ?functionalClaim.
?functionalClaim ps:P1317 ?functional.
BIND(IF(?functional, "Operational", "Not operational") AS ?functionalLabel)
}
OPTIONAL {
?lighthouse rdfs:label ?lighthouseName.
FILTER (LANG(?lighthouseName) = 'en')
}
OPTIONAL {
?lighthouse schema:description ?lighthouseName.
FILTER (LANG(?lighthouseName) = 'en')
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?lighthouseName

SELECT ?prop ?propLabel ?prop_items ?prop_stmts ?val ?valLabel ?val_count ?samp ?sampLabel
WITH {
SELECT ?item ?prop ?stmt ?val WHERE {
hint:Query hint:optimizer "None" .
wd:Q4006 ^wdt:P279*/^wdt:P31 ?item .
MINUS {?item wdt:P31 wd:Q17146139}
?item ?p ?stmt .
?prop wikibase:claim ?p .
?prop wikibase:statementProperty ?ps .
MINUS {
{?prop wdt:P31/wdt:P279* wd:Q19847637} # Wikidata property representing a unique identifier
UNION
{?prop wdt:P31/wdt:P279* wd:Q18614948} # Wikidata property for authority control
}
?stmt ?ps ?val .
} #LIMIT 2000
} AS %maps_props_vals
WITH {
SELECT ?prop (COUNT(DISTINCT(?item)) AS ?prop_items) (COUNT(DISTINCT(?stmt)) AS ?prop_stmts) WHERE {
INCLUDE %maps_props_vals
} GROUP BY ?prop
} AS %prop_stats
WITH {
SELECT ?prop ?val (COUNT(DISTINCT(?item)) AS ?val_count) (SAMPLE(?item) AS ?samp) WHERE {
INCLUDE %maps_props_vals
} GROUP BY ?prop ?val
HAVING (?val_count > 3)
} AS %prop_val_counts
WITH {
SELECT ?prop ?val ?samp ?val_count (COUNT(DISTINCT(?val1)) AS ?val_rank) WHERE {
INCLUDE %prop_val_counts .
{
SELECT ?prop (?val AS ?val1) (?val_count AS ?val1_count) WHERE {
INCLUDE %prop_val_counts
}
}
FILTER (?val1_count >= ?val_count)
} GROUP BY ?prop ?val ?val_count ?samp
} AS %prop_val_ranks
WHERE {
INCLUDE %prop_stats .
INCLUDE %prop_val_ranks .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
FILTER (?val_rank < 6) .
} ORDER BY DESC(?prop_items) DESC(?prop_stmts) ?prop ?val_rank

SELECT ?occupationLabel ?women ?men WITH {
SELECT ?occupation (SUM(?woman) AS ?women) (SUM(?man) AS ?men) WHERE {
BIND(wd:Q30 AS ?country). # substitute country of your choice here (remove the Q30, hit Ctrl+Space and start typing the country name, select the right one from the suggestions with the arrow keys and insert it with Enter)
?person wdt:P31 wd:Q5;
wdt:P27 ?country; # remove this to search world-wide - results in query timeout unless you reduce the dataset in some other fashion
p:P106/ps:P106 ?occupation.
{ ?person wdt:P21 wd:Q6581097. BIND(1 AS ?man). } UNION
{ ?person wdt:P21 wd:Q2449503. BIND(1 AS ?man). } UNION
{ ?person wdt:P21 wd:Q6581072. BIND(1 AS ?woman). } UNION
{ ?person wdt:P21 wd:Q1052281. BIND(1 AS ?woman). }
# TODO consider how to count P21: Q48270 (genderqueer) and Q1097630 (intersex)
}
GROUP BY ?occupation
} AS %results WHERE {
INCLUDE %results. # subquery as optimization: don't make the label service fetch labels for every ?person in the subquery
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY
# divide ?variable+1 instead of ?variable to avoid division by zero
# (unfortunately, we can't use ABS(LOG(x/y)) instead of the IF() because SPARQL has no LOG function)
DESC(IF(?women > ?men, (?women+1)/(?men+1), (?men+1)/(?women+1)))
# if the ratio is the same, show results with more people in total first
DESC(?women+?men)

SELECT ?iso ?countryLabel (SUM(?stars) as ?stars) ?fertility WHERE {
{SELECT DISTINCT ?country ?iso WHERE {
VALUES ?countrytypes {wd:Q6256 wd:Q3624078} # country and sovereign state
?country wdt:P31 ?countrytypes ; wdt:P298 ?iso
MINUS {?country wdt:P576 []} # Not dissolved
} }
?country wdt:P163 ?flag.
OPTIONAL{
?flag p:P180 [ps:P180 ?feature ; pq:P1114 ?stars] . # quantity of feature
?feature wdt:P279? wd:Q836708 # type of star polygon
}
OPTIONAL { ?country wdt:P4841 ?fertility }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} GROUP BY ?iso ?countryLabel ?fertility
ORDER BY DESC(?stars) ?countryLabel

