# Find parent taxon shared by two taxa:
SELECT ?via ?viaLabel ?rank ?rankLabel ?pic WHERE {
?via ^(wdt:P171*) wd:Q15314291; # Alocasia cuprea (Q15314291)
^(wdt:P171*) wd:Q1345646. # Codiaeum variegatum (Q1345646)
FILTER(NOT EXISTS {
?via2 ^(wdt:P171*) wd:Q15314291; # Alocasia cuprea (Q15314291)
^(wdt:P171*) wd:Q1345646; # Codiaeum variegatum (Q1345646)
wdt:P171 ?via.
})
OPTIONAL {
?via wdt:P18 ?pic;
wdt:P105 ?rank.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

