}

SELECT ?station ?stationLabel ?cds ?line ?layer WHERE {
{ SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.BFS" ; gas:in wd:Q15213944 ; gas:target wd:Q2784062 ; gas:out ?station ; gas:out1 [] ; gas:out2 ?pred .
gas:program gas:linkType wdt:P197 . } }
FILTER(?station != wd:Q15213944)
?pred p:P625/psv:P625/wikibase:geoLatitude ?lat1 ; p:P625/psv:P625/wikibase:geoLongitude ?lon1 .
?station p:P625/psv:P625/wikibase:geoLatitude ?lat2 ; p:P625/psv:P625/wikibase:geoLongitude ?lon2 .
BIND(CONCAT('LINESTRING(', STR(?lon1), ' ', STR(?lat1), ',', STR(?lon2), ' ', STR(?lat2), ')') AS ?str) . BIND(STRDT(?str, geo:wktLiteral) AS ?line)
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?xLabel ?size ?rgb WITH {
SELECT DISTINCT ?n WHERE { # generate a sequence of natural numbers
VALUES ?start { 1 }
BIND (2000 AS ?end)
BIND ( (?end - ?start ) + 1 AS ?x )
[] p:P31 [
ps:P31 wd:Q21199 ; # is a natural number
pq:P155 ?prev
] .
?prev wdt:P1181 ?n .
FILTER (?n > 0 && ?n < ?x + 1)
}
} AS %numbers
WHERE {
INCLUDE %numbers
?x wdt:P31 wd:Q21199 .
?x wdt:P1181 ?n .
FILTER (?x NOT IN (wd:Q713113)) # exclude the annoying 0.999
OPTIONAL { ?x wdt:P31 wd:Q49008 . BIND (true AS ?prime) } # highlight prime numbers
BIND(1 AS ?size) # used for the size of the bubble: want them all the same size
BIND ( COALESCE(IF(?prime, "FD7F7F", 1/0),"71C1FD") AS ?rgb )
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?n

